"""Exclusive qualification window. Always restore the current four-slot backend."""
import datetime, fcntl, hashlib, json, os, re, subprocess, sys, time, urllib.error, urllib.request
from pathlib import Path

LAB=Path('/data2/llm-models/glm53-dynamic-production-20261017')
ROOT=Path('/data2/llm-models/glm53-dynamic-kv-20261017/managed1152kv4')
BASE=Path('/data2/llm-models/glm53-four-active-20261016/slots4v2')
OUT=LAB/'receipts/runtime2'
PY='/data2/llm-models/glm53-exl3-trial/.venv/bin/python'
PROD='glm53-b2.service'; TRIAL='glm53-managed-production-probe.service'
SHA='f0a25e2c707748eed0679d7e58f92907ebd6eea4e3b2b1605037382baeb2d046'
PROFILE='6ce2525ba4631923850d429649157cf2f8ff2bd6339907e76e0abe15a33b22e5'
def cmd(a,**kw):return subprocess.run(a,check=True,**kw)
def write(name,value): (OUT/name).write_text(json.dumps(value,indent=2)+'\n')
def log(event,**kw):
 row={'utc':datetime.datetime.now(datetime.timezone.utc).isoformat(),'event':event,**kw}
 print(json.dumps(row),flush=True)
 with (OUT/'events.jsonl').open('a') as f:f.write(json.dumps(row)+'\n')
def health(port):
 try:r=urllib.request.urlopen(f'http://127.0.0.1:{port}/health',timeout=5)
 except urllib.error.HTTPError as e:r=e
 with r:return json.load(r)
def idle(h):
 assert h['status']=='ok' and h['native_extension']['sha256']==SHA
 assert h['max_active_sequences']==4
 assert not any(h.get(k) for k in ('busy','active_sequences','pending_sequences','admitted_requests'))
 assert not h['request_metrics']['active'] and not h['request_queue']['waiting']
 assert not h['concurrent_ring']['active_ring_leases']
 assert not h.get('switcher',{}).get('inflight') and not h.get('switcher',{}).get('waiting')
def owners():return set(map(int,subprocess.check_output(['nvidia-smi','--query-compute-apps=pid','--format=csv,noheader'],text=True).split()))
def unit(name=PROD):
 return dict(l.split('=',1) for l in subprocess.check_output(['systemctl','--user','show',name,'-p','MainPID','-p','ControlGroup','-p','ActiveState','-p','NRestarts'],text=True).splitlines())
def verify():
 sys.path.insert(0,str(LAB/'tools'));from prepare_row16 import verify as verify_engine
 verify_engine(ROOT/'engine',ROOT/'engine.sha256')
 manifest=json.loads((ROOT/'service-sha256.json').read_text())
 assert set(manifest)=={str(p.relative_to(ROOT/'service')) for p in (ROOT/'service').rglob('*.py')}
 for rel,digest in manifest.items():assert hashlib.sha256((ROOT/'service'/rel).read_bytes()).hexdigest()==digest
 native,=(ROOT/'native').glob('exllamav3_ext*.so');assert hashlib.sha256(native.read_bytes()).hexdigest()==SHA
 assert hashlib.sha256((ROOT/'engine/exllamav3/util/managed_kv_allocator.so').read_bytes()).hexdigest()=='95fa84c848c9660016caeea51e633d26c11669ef4e2f512ba19636e25ba3ec7e'
 return {'engine_files':len((ROOT/'engine.sha256').read_text().splitlines()),'service_files':len(manifest)}
def foreign():
 # Router /health omits its counters while its backend is unavailable. Also
 # inspect access events, so that a POST during a private window is not missed.
 started=json.loads((OUT/'guard.json').read_text())['since']
 scan=subprocess.run(['journalctl','-u','glm-qwen-switcher.service','--since',started,'--no-pager','-o','cat','--grep','"POST '],text=True,capture_output=True)
 assert scan.returncode in (0,1),scan.stderr
 if scan.stdout.strip():raise RuntimeError('Foreign router POST observed; yield and restore')
 try:h=health(8012)
 except (OSError,ValueError):h={}
 s=h.get('switcher',{})
 if s.get('inflight') or s.get('waiting'):raise RuntimeError('Foreign router lease; yield and restore')
 if (OUT/'stopped.json').exists() and unit()['ActiveState'] not in ('inactive','failed'):
  raise RuntimeError('Production unit was externally started; yield')
def ready(port):
 began=time.monotonic()
 while time.monotonic()-began<480:
  try:
   h=health(port)
   if h.get('status')=='ok':
    idle(h);assert h['weightless']['numerics_verified_devices']==['cuda:0','cuda:1']
    if port==8013:
     assert h['cache_tokens']==1187840 and h['profile_digest']==PROFILE
     assert h['experimental_active_kv']['backing']=='cuda_managed_latent'
    else:assert h['cache_tokens']==655360 and h['profile_digest']=='6c5aaeaa0fc5640f3015593a2c1b97570a95b08d97df10ed905923be84459f69'
    return h
  except (OSError,ValueError,KeyError):pass
  if port==8013:
   foreign()
   if unit(TRIAL)['ActiveState'] in ('failed','inactive'):raise RuntimeError('Private API exited during startup')
  time.sleep(2)
 raise TimeoutError('Model readiness')
def restore():
 if not (OUT/'before.json').exists():return
 subprocess.run(['systemctl','--user','stop',TRIAL],timeout=120)
 cmd(['systemctl','--user','start',PROD],timeout=120)
 h=ready(8012);write('restored.json',h);write('restored-unit.json',unit())
 log('restored_current_four_slot_production')
def quiet(label):
 stable=0;began=time.monotonic();log('wait_cpu_quiet',step=label)
 while time.monotonic()-began<600:
  if (OUT/'guard.json').exists():foreign()
  psi=float(re.search(r'avg10=([0-9.]+)',Path('/proc/pressure/cpu').read_text()).group(1))
  stable=stable+1 if psi<2 else 0
  if stable>=20:return
  time.sleep(1)
 raise TimeoutError('CPU quiet interval unavailable')
def launch(index):
 assert not owners()
 plan=json.loads((ROOT/'launch-plan.json').read_text());argv=plan['argv'][:]
 argv[argv.index('--disk_cache_dir')+1]=str(LAB/'disk-cache')
 args=['systemd-run','--user','--unit='+TRIAL,'--collect','--property=KillMode=mixed',
  '--property=TimeoutStopSec=60','--property=RuntimeMaxSec=3600','--property=LimitNOFILE=65536',
  '--property=Restart=no','--property=StandardOutput=append:'+str(OUT/f'api-{index}.log'),
  '--property=StandardError=append:'+str(OUT/f'api-{index}.log'),'--working-directory='+str(ROOT)]
 for k,v in plan['env'].items():args.append('--setenv='+k+'='+v)
 cmd(args+argv,timeout=30);log('loading',index=index)
 h=ready(8013);write(f'ready-{index}.json',h);write(f'unit-{index}.json',unit(TRIAL));log('ready',index=index)
 return h
def resources():
 mem={k:int(v.split()[0])*1024 for k,v in (x.split(':',1) for x in Path('/proc/meminfo').read_text().splitlines())}
 cg=unit(TRIAL)['ControlGroup'];base=Path('/sys/fs/cgroup')/cg.lstrip('/')
 return {'available_bytes':mem['MemAvailable'],'memory_current':int((base/'memory.current').read_text()),
  'memory_events':(base/'memory.events').read_text(),'memory_psi':Path('/proc/pressure/memory').read_text()}
def step(label,argv,timeout,env=None,scored=False):
 foreign();log('step_begin',step=label);began=time.monotonic();samples=[]
 with (OUT/(label+'.log')).open('w') as f:
  p=subprocess.Popen(argv,stdout=f,stderr=subprocess.STDOUT,env=env)
  try:
   while p.poll() is None:
    foreign();psi=float(re.search(r'avg10=([0-9.]+)',Path('/proc/pressure/cpu').read_text()).group(1))
    row={'seconds':time.monotonic()-began,'cpu_psi_avg10_pct':psi,**resources()};samples.append(row)
    assert row['available_bytes']>=16*1024**3,'Host RAM headroom below 16GiB'
    assert not re.search(r'oom(?:_kill)? [1-9]',row['memory_events']),'Candidate cgroup OOM'
    if time.monotonic()-began>timeout:raise TimeoutError(label)
    time.sleep(1)
   if p.returncode:raise subprocess.CalledProcessError(p.returncode,argv)
  finally:
   if p.poll() is None:p.terminate();p.wait(timeout=30)
   write(label+'-resources.json',{'valid_timing':all(s['cpu_psi_avg10_pct']<2 for s in samples),'samples':samples})
 if scored and any(s['cpu_psi_avg10_pct']>=2 for s in samples):raise RuntimeError('CPU timing contaminated: '+label)
 log('step_pass',step=label,seconds=time.monotonic()-began)
def main():
 OUT.mkdir(parents=True,exist_ok=False)
 locks=[]
 for path in (LAB/'window.lock',Path('/data2/llm-models/glm53-dynamic-kv-20261017/window.lock')):
  f=path.open('w');fcntl.flock(f,fcntl.LOCK_EX|fcntl.LOCK_NB);locks.append(f)
 write('source-verified.json',verify())
 quiet('before-maintenance')
 cmd([PY,'/data2/llm-models/glm53-four-slot-qualification-20261016/inspect_production.py',str(OUT/'baseline-inspection.json')],timeout=90)
 for _ in range(3):h=health(8012);idle(h);time.sleep(1)
 u=unit();assert str(BASE/'service/glm/glm_api.py').encode() in Path('/proc/'+u['MainPID']+'/cmdline').read_bytes()
 pids=set(map(int,(Path('/sys/fs/cgroup')/u['ControlGroup'].lstrip('/')/'cgroup.procs').read_text().split()))
 assert owners() and owners()<=pids
 assert subprocess.run(['systemctl','is-active','--quiet','qwen-flash-vllm.service']).returncode
 write('guard.json',{'since':datetime.datetime.now(datetime.timezone.utc).isoformat()})
 write('before.json',h);write('before-unit.json',u);log('exclusive_window_begin')
 try:
  cmd(['systemctl','--user','stop',PROD],timeout=120);assert not owners();write('stopped.json',unit())
  launch(0)
  tools=LAB/'tools';url='http://127.0.0.1:8013'
  step('lifecycle',[PY,str(tools/'qualify_active_sequences.py'),'--base-url',url,'--output',str(OUT/'lifecycle.json')],420)
  quiet('warmup')
  step('warmup',[PY,str(tools/'sustained.py'),'--base-url',url,'--agents','4','--active-sequences','4','--requests','8','--effort','low','high','--output',str(OUT/'warmup')],350)
  quiet('short')
  step('short',[PY,str(tools/'sustained.py'),'--base-url',url,'--agents','4','--active-sequences','4','--requests','24','--effort','low','high','--output',str(OUT/'short')],650,scored=True)
  quiet('long')
  cases='/data2/llm-models/glm53-active-kv-20261017/cases'
  step('long',[PY,str(tools/'probe_active_kv.py'),'--base-url',url,'--output',str(OUT/'long'),'--cases',cases],1900,scored=True)
  cmd(['systemctl','--user','stop',TRIAL],timeout=120);assert not owners();launch(1)
  step('restore',[PY,str(tools/'qualify_managed_runtime.py'),'--base-url',url,'--mode','restore','--seed',str(OUT/'long'),'--cases',cases,'--output',str(OUT/'restore')],900)
  plan=json.loads((ROOT/'launch-plan.json').read_text())
  step('functional',[PY,str(LAB/'functional2.py')],480,env={**os.environ,**plan['env']})
  quiet('soak')
  step('soak',[PY,str(tools/'qualify_managed_runtime.py'),'--base-url',url,'--mode','soak','--seconds','900','--output',str(OUT/'soak')],1150,scored=True)
  h=health(8013);idle(h);write('final.json',h);write('final-unit.json',unit(TRIAL));verify()
  for name in ('lifecycle.json','long/summary.json','restore/summary.json','functional/summary.json','soak/summary.json'):
   assert json.loads((OUT/name).read_text())['passed'],name
  assert unit(TRIAL)['NRestarts']=='0'
  write('accepted.json',{'passed':True,'root':str(ROOT),'profile_digest':PROFILE,'native_sha256':SHA,'max_active_sequences':4,'pool_tokens':1187840})
  log('qualification_pass')
 except BaseException as e:
  write('failure.json',{'type':type(e).__name__,'message':str(e)});log('failure',error=type(e).__name__,message=str(e));raise
 finally:restore()
if __name__=='__main__':
 if '--restore-only' in sys.argv:restore()
 else:main()
